import { useEffect, useRef } from "react";
import { ArrowUpRight } from "lucide-react";
import AppIcon from "./AppIcon";
import TransitionLink from "./TransitionLink";
import { projectById } from "../data/projects";
import { loadProject, prefersReducedMotion } from "../routes";
import "./Inline.css";

// A looping clip of a real project, sitting inside a sentence. Opens the project.
export function InlineClip({ clip, project, index = 0 }) {
  const info = projectById(project);
  const ref = useRef(null);

  // Plays only while on screen, and never for people who asked for less motion.
  useEffect(() => {
    const video = ref.current;
    if (!video) return undefined;
    if (prefersReducedMotion()) {
      video.pause();
      return undefined;
    }
    if (typeof IntersectionObserver === "undefined") return undefined;
    const observer = new IntersectionObserver(([entry]) => {
      if (entry.isIntersecting) video.play().catch(() => {});
      else video.pause();
    });
    observer.observe(video);
    return () => observer.disconnect();
  }, []);

  if (!info) return null;
  return (
    <TransitionLink
      to={`/work/${project}`}
      prepare={loadProject}
      morph
      className="inline-clip"
      style={{ "--w": index }}
      aria-label={`${info.title}, ${info.category}`}
    >
      <span className="inline-clip-media" data-morph>
        <video
          ref={ref}
          src={`/media/hero/${clip}.mp4`}
          poster={`/media/hero/${clip}.webp`}
          muted
          loop
          playsInline
          autoPlay
          preload="auto"
          aria-hidden="true"
        />
      </span>
      <span className="inline-clip-tip" aria-hidden="true">
        {info.title}
        <ArrowUpRight strokeWidth={2.4} />
      </span>
    </TransitionLink>
  );
}

// A small photo chip; decorative, the sentence already says what it shows.
export function InlinePhoto({ src, index = 0 }) {
  return (
    <span className="inline-photo" style={{ "--w": index }} aria-hidden="true">
      <img src={src} alt="" loading="lazy" decoding="async" />
    </span>
  );
}

// An app icon chip, e.g. Mail next to "inbox".
export function InlineIcon({ tone, children, index = 0 }) {
  return (
    <span className="inline-icon" style={{ "--w": index }} aria-hidden="true">
      <AppIcon tone={tone} size={40}>
        {children}
      </AppIcon>
    </span>
  );
}
