import { useEffect, useRef, useState } from "react";
import { Link } from "react-router-dom";
import { PROJECT_ICONS, iconFor } from "../icons";
import { loadProject, loadWork, prefetchWork, prefersReducedMotion } from "../../routes";
import TransitionLink from "../TransitionLink";
import "./ProjectFolder.css";

// Short preview loops for the featured projects, played while a file is hovered.
const CLIPS = {
  pumpkinclick: "pumpkin",
  crackanegg: "egg",
  luckyblock: "lucky",
  scangame: "scan",
};

// Closed at rest. Opens while hovered or focused; on touch screens (no hover)
// it opens while it sits in the middle of the viewport and closes as it leaves.
function useFolderOpen(ref) {
  const [open, setOpen] = useState(false);

  useEffect(() => {
    const el = ref.current;
    if (!el || typeof IntersectionObserver === "undefined") return undefined;
    const canHover = window.matchMedia?.("(hover: hover) and (pointer: fine)").matches;

    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          const idle = window.requestIdleCallback || ((fn) => setTimeout(fn, 200));
          idle(prefetchWork);
        }
        if (!canHover) setOpen(entry.intersectionRatio >= 0.75);
      },
      { threshold: [0, 0.4, 0.75], rootMargin: "-10% 0px -10% 0px" }
    );
    observer.observe(el);
    return () => observer.disconnect();
  }, [ref]);

  return [open, setOpen];
}

function Sheet({ project, index, count, hot, onHot }) {
  const Icon = iconFor(project.icon, PROJECT_ICONS);
  const video = useRef(null);
  const clip = CLIPS[project.id];
  const live = hot === index;

  useEffect(() => {
    const v = video.current;
    if (!v) return;
    if (live && !prefersReducedMotion()) {
      v.currentTime = 0;
      v.play().catch(() => {});
    } else {
      v.pause();
    }
  }, [live]);

  // Neighbours make room: the next file over moves furthest, the ones beyond it less.
  const lean = hot === null || live ? 0 : Math.sign(index - hot) * (Math.abs(index - hot) === 1 ? 1 : 0.6);

  return (
    <li
      className={`folder-slot ${live ? "is-hot" : ""}`}
      style={{ "--c": index - (count - 1) / 2, "--i": index, "--lean": lean }}
      onPointerEnter={() => onHot(index)}
      onPointerLeave={() => onHot(null)}
    >
      <TransitionLink
        className="sheet"
        to={`/work/${project.id}`}
        prepare={loadProject}
        morph
        onFocus={() => onHot(index)}
        onBlur={() => onHot(null)}
      >
        <span className="sheet-caption">
          <span className="sheet-icon" aria-hidden="true">
            <Icon strokeWidth={2} />
          </span>
          <span className="sheet-title">{project.title}</span>
        </span>
        <span className="sheet-media" data-morph>
          <img
            src={project.image.src}
            srcSet={project.image.srcSet}
            sizes="(max-width: 700px) 50vw, 280px"
            width="640"
            height="400"
            alt=""
            decoding="async"
          />
          {clip && (
            <video
              ref={video}
              className={live ? "is-live" : ""}
              src={`/media/hero/${clip}.mp4`}
              muted
              loop
              playsInline
              preload="none"
              aria-hidden="true"
            />
          )}
        </span>
      </TransitionLink>
    </li>
  );
}

function ProjectFolder({ projects, total }) {
  const ref = useRef(null);
  const [open, setOpen] = useFolderOpen(ref);
  const [hot, setHot] = useState(null);

  return (
    <div
      ref={ref}
      className={`folder ${open ? "is-open" : ""} ${hot !== null ? "has-hot" : ""}`}
      onPointerEnter={(e) => {
        prefetchWork();
        if (e.pointerType === "mouse") setOpen(true);
      }}
      onPointerLeave={(e) => {
        if (e.pointerType === "mouse") setOpen(false);
      }}
      onFocus={() => setOpen(true)}
      onBlur={(e) => {
        if (!e.currentTarget.contains(e.relatedTarget)) setOpen(false);
      }}
    >
      <div className="folder-body">
        <Link className="folder-back" to="/work" tabIndex={-1} aria-hidden="true">
          <span className="folder-tab" />
        </Link>

        <ul className="folder-sheets" aria-label="Featured projects">
          {projects.map((project, i) => (
            <Sheet
              key={project.id}
              project={project}
              index={i}
              count={projects.length}
              hot={hot}
              onHot={setHot}
            />
          ))}
        </ul>

        <span className="folder-lip" aria-hidden="true" />

        <TransitionLink
          className="folder-front"
          to="/work"
          prepare={loadWork}
          pairs={() => [[ref.current?.querySelector(".folder-body"), "work-folder"]]}
          aria-label={`Work, open the archive of ${total} projects`}
        >
          <span className="folder-mark" aria-hidden="true">
            {Array.from({ length: 9 }, (_, i) => (
              <span key={i} className={i === 4 ? "is-core" : undefined} />
            ))}
          </span>
        </TransitionLink>
      </div>

      <p className="folder-hint" aria-hidden="true">
        <span className="folder-hint-touch">Tap a file to open it</span>
      </p>
    </div>
  );
}

export default ProjectFolder;
