import { useEffect, useRef, useState } from "react";

// Headline that reveals word by word. Screen readers get the sentence once.
export function RevealText({ as: Tag = "span", text, className = "", delay = 0, ...rest }) {
  const words = text.split(" ");
  return (
    <Tag
      className={className}
      data-reveal="text"
      style={delay ? { "--reveal-delay": `${delay}ms` } : undefined}
      {...rest}
    >
      <span className="sr-only">{text}</span>
      <span aria-hidden="true">
        {words.map((word, i) => (
          <span key={`${word}-${i}`}>
            <span className="rt-w" style={{ "--w": i }}>
              {word}
            </span>
            {i < words.length - 1 ? " " : null}
          </span>
        ))}
      </span>
    </Tag>
  );
}

const WEIGHTS = { light: 1.5, regular: 1.8, medium: 2, semibold: 2.25, bold: 2.5 };

// An inline icon that behaves like an SF Symbol: sized to the text, weight-matched,
// and able to play an effect whenever `trigger` changes.
export function Sym({ icon: Icon, weight = "regular", effect, trigger, className = "", ...rest }) {
  const [playing, setPlaying] = useState(0);
  const first = useRef(true);

  useEffect(() => {
    if (first.current) {
      first.current = false;
      return;
    }
    if (effect) setPlaying((n) => n + 1);
  }, [trigger, effect]);

  const play = effect && playing ? ` is-${effect}` : effect === "pulse" ? " is-pulse" : "";
  return (
    <span key={playing} className={`sym${play} ${className}`} aria-hidden="true" {...rest}>
      <Icon strokeWidth={WEIGHTS[weight] || WEIGHTS.regular} />
    </span>
  );
}

// Replace transition between two symbols, like SF Symbols' .replace effect.
export function SymbolSwap({ on, off: Off, to: On, weight = "regular", className = "" }) {
  const stroke = WEIGHTS[weight] || WEIGHTS.regular;
  return (
    <span className={`sym-swap ${className}`} aria-hidden="true">
      <Off className={on ? "is-off" : ""} strokeWidth={stroke} />
      <On className={on ? "" : "is-off"} strokeWidth={stroke} />
    </span>
  );
}

const DIGITS = "0123456789".split("");

// Text whose digits roll like an odometer when they change.
export function Roll({ value, className = "" }) {
  return (
    <span className={`roll ${className}`}>
      <span className="sr-only">{value}</span>
      {String(value)
        .split("")
        .map((ch, i) =>
          /\d/.test(ch) ? (
            <span key={i} className="roll-col" aria-hidden="true">
              <span className="roll-strip" style={{ "--d": Number(ch) }}>
                {DIGITS.map((d) => (
                  <span key={d}>{d}</span>
                ))}
              </span>
            </span>
          ) : (
            <span key={i} aria-hidden="true">
              {ch}
            </span>
          )
        )}
    </span>
  );
}
