import { useLayoutEffect, useRef, useState } from "react";
import { flushSync } from "react-dom";
import { X } from "lucide-react";
import { PLACES } from "../../data/places";
import { prefersReducedMotion } from "../../routes";
import Statement from "../Statement";
import { InlinePhoto } from "../Inline";
import "./Places.css";

const SLOTS = 5;

const metaLine = (place) => [place.country, place.year].filter(Boolean).join(" · ");
const describe = (place) => place.alt || `${place.location}, ${place.country}`;

function Postcard({ tint = ["#b9d3ea", "#efe6dc"] }) {
  return (
    <span className="postcard" style={{ "--c1": tint[0], "--c2": tint[1] }} aria-hidden="true">
      <span className="postcard-sun" />
      <span className="postcard-far" />
      <span className="postcard-near" />
    </span>
  );
}

function PlaceCard({ place, onOpen }) {
  const media = (
    <span className="place-media">
      {place.image ? (
        <img
          src={place.image}
          alt={describe(place)}
          loading="lazy"
          decoding="async"
        />
      ) : (
        <Postcard tint={place.tint} />
      )}
    </span>
  );

  const caption = (
    <span className="place-caption">
      <span className="place-location">{place.location}</span>
      <span className="place-meta">{metaLine(place)}</span>
    </span>
  );

  const className = `place-card ${place.image ? "" : "is-placeholder"}`;

  if (!place.image) {
    return (
      <figure className={className}>
        {media}
        <figcaption>{caption}</figcaption>
      </figure>
    );
  }

  return (
    <button
      type="button"
      className={className}
      onClick={onOpen}
      aria-label={`View photo: ${place.location}, ${metaLine(place)}`}
    >
      {media}
      {caption}
    </button>
  );
}

function PlaceViewer({ place, onClose, morphed }) {
  const ref = useRef(null);

  // Layout effect: the dialog must be open before a View Transition snapshots the new state.
  useLayoutEffect(() => {
    const dialog = ref.current;
    if (!dialog) return undefined;
    const opener = document.activeElement;
    if (dialog.showModal) dialog.showModal();
    else dialog.setAttribute("open", "");
    document.body.classList.add("is-locked");
    return () => {
      document.body.classList.remove("is-locked");
      if (dialog.open && dialog.close) dialog.close();
      if (opener?.isConnected) opener.focus({ preventScroll: true });
    };
  }, []);

  return (
    <dialog
      ref={ref}
      className={`viewer ${morphed ? "is-morphed" : ""}`}
      aria-label={`${place.location}, ${metaLine(place)}`}
      onCancel={(e) => {
        e.preventDefault();
        onClose();
      }}
      onClick={(e) => {
        if (e.target === ref.current) onClose();
      }}
    >
      <figure className="viewer-figure">
        <img src={place.image} alt={describe(place)} />
        <figcaption className="viewer-caption">
          <span className="viewer-location">{place.location}</span>
          <span className="viewer-meta">{metaLine(place)}</span>
        </figcaption>
      </figure>
      <button type="button" className="viewer-close glass" onClick={onClose} aria-label="Close photo">
        <X aria-hidden="true" strokeWidth={2.2} />
      </button>
    </dialog>
  );
}

const photoAt = (i) => document.querySelector(`#places .place-slot[data-slot="${i + 1}"] .place-media img`);

// Opens/closes the viewer inside a View Transition so the photo grows out of its card
// (and shrinks back into it). Only one element carries the shared name at a time.
function morphPhoto(update, { from, to }) {
  const root = document.documentElement;
  if (!document.startViewTransition || prefersReducedMotion()) {
    update();
    return false;
  }
  if (from) from.style.viewTransitionName = "place-photo";
  root.dataset.vt = "photo";
  const transition = document.startViewTransition(() => {
    if (from) from.style.viewTransitionName = "";
    flushSync(update);
    if (to) to.style.viewTransitionName = "place-photo";
  });
  transition.ready.catch(() => {});
  transition.finished.finally(() => {
    if (to) to.style.viewTransitionName = "";
    delete root.dataset.vt;
  });
  return true;
}

function Places() {
  const [openIndex, setOpenIndex] = useState(null);
  const [morphed, setMorphed] = useState(false);
  const places = PLACES.slice(0, SLOTS);
  if (!places.length) return null;

  const open = (i) => {
    const from = photoAt(i);
    setMorphed(!!from && !prefersReducedMotion() && !!document.startViewTransition);
    morphPhoto(() => setOpenIndex(i), { from });
  };
  const close = () => {
    const to = openIndex !== null ? photoAt(openIndex) : null;
    morphPhoto(() => setOpenIndex(null), { to });
  };

  return (
    <section id="places" className="section home-places" data-nav-section="about">
      <div className="shell">
        <div className="places-grid" data-count={places.length}>
          <header className="places-head" data-reveal>
            <Statement
              size="m"
              lead="Places."
              text="Photos from {a} wherever I end up {b} between projects."
              media={{
                a: <InlinePhoto src={PLACES[1]?.image} />,
                b: <InlinePhoto src={PLACES[0]?.image} />,
              }}
            />
          </header>

          {places.map((place, i) => (
            <div
              key={`${place.location}-${i}`}
              className="place-slot"
              data-slot={i + 1}
              data-reveal
              style={{ "--reveal-delay": `${(i % 3) * 60}ms` }}
            >
              <PlaceCard place={place} onOpen={() => open(i)} />
            </div>
          ))}
        </div>
      </div>

      {openIndex !== null && places[openIndex]?.image && (
        <PlaceViewer place={places[openIndex]} onClose={close} morphed={morphed} />
      )}
    </section>
  );
}

export default Places;
