import { useEffect, useRef, useState } from "react";
import { ArrowUpRight, Braces, Gauge, Hammer, SlidersHorizontal } from "lucide-react";
import { ABOUT, CURRENTLY, PRINCIPLES, PROFILE, STATUS } from "../../data/profile";
import { projectById } from "../../data/projects";
import TransitionLink from "../TransitionLink";
import { loadProject, prefersReducedMotion } from "../../routes";
import { Roll, Sym } from "../motion";
import Statement, { useScrollLit } from "../Statement";
import useLocalTime from "../../hooks/useLocalTime";
import "./About.css";

const PRINCIPLE_ICONS = [Gauge, Braces, SlidersHorizontal];

// The story, set large. Its words light up as it scrolls through, like the headlines.
function Story() {
  const ref = useRef(null);
  useScrollLit(ref);

  return (
    <div className="about-story" ref={ref} data-reveal>
      {ABOUT.paragraphs.map((text) => (
        <p key={text.slice(0, 24)}>
          {text.split(" ").map((word, i) => (
            <span className="st-word" key={i}>
              {word}{" "}
            </span>
          ))}
        </p>
      ))}
    </div>
  );
}

// A spec sheet: availability and local time on top, then the facts, divided by hairlines.
function Specs() {
  const { time, hour } = useLocalTime(PROFILE.timeZone);
  const asleep = hour < 7;

  return (
    <div className="about-specs">
      <div className="spec-status" data-reveal>
        <p className="spec-status-line">
          <span className={`status-dot ${STATUS.state === "busy" ? "is-busy" : ""}`} aria-hidden="true" />
          <span className="spec-status-word">
            {STATUS.label} {STATUS.detail}
          </span>
          <span className="spec-clock">
            <time><Roll value={time} /></time> in {PROFILE.location}
            {asleep ? ", probably asleep" : ""}
          </span>
        </p>
        <p className="spec-note">{STATUS.note}</p>
      </div>

      <dl className="spec-list">
        {ABOUT.facts.map((fact) => (
          <div className="spec-row" key={fact.label} data-reveal>
            <dt>{fact.label}</dt>
            <dd>{fact.value}</dd>
          </div>
        ))}
      </dl>
    </div>
  );
}

function usePlayWhileVisible(ref) {
  const [visible, setVisible] = useState(false);
  useEffect(() => {
    const el = ref.current;
    if (!el || typeof IntersectionObserver === "undefined" || prefersReducedMotion()) return undefined;
    const observer = new IntersectionObserver(([entry]) => setVisible(entry.isIntersecting), { threshold: 0.25 });
    observer.observe(el);
    return () => observer.disconnect();
  }, [ref]);

  useEffect(() => {
    const video = ref.current?.querySelector("video");
    if (!video) return;
    if (visible) video.play().catch(() => {});
    else video.pause();
  }, [ref, visible]);
}

// What's on the bench, shown as a wide film rather than a card. It grows into the project page.
function Building() {
  const ref = useRef(null);
  usePlayWhileVisible(ref);
  const project = projectById(CURRENTLY.building);
  if (!project) return null;

  return (
    <TransitionLink
      ref={ref}
      to={`/work/${project.id}`}
      prepare={loadProject}
      morph
      className="about-now"
      data-reveal
      aria-label={`Currently building: ${project.title}. ${project.shortDescription}`}
    >
      <span className="now-media" data-morph>
        <video
          src="/media/about/scan-wide.mp4"
          poster="/media/about/scan-wide.webp"
          muted
          loop
          playsInline
          preload="none"
          aria-hidden="true"
        />
      </span>
      <span className="now-caption" aria-hidden="true">
        <span className="now-text">
          <span className="now-label">
            <Hammer strokeWidth={2} />
            Currently building
          </span>
          <span className="now-title">{project.title}</span>
          <span className="now-line">{project.shortDescription}</span>
        </span>
        <span className="now-side">
          {project.status && (
            <span className="now-status">
              <span className="now-pulse" />
              {project.status}
            </span>
          )}
          <span className="now-open">
            <ArrowUpRight strokeWidth={2.2} />
          </span>
        </span>
      </span>
    </TransitionLink>
  );
}

function Principles() {
  return (
    <ol className="about-principles">
      {PRINCIPLES.map((principle, i) => (
        <li className="principle" key={principle.title} data-reveal>
          <Sym icon={PRINCIPLE_ICONS[i % PRINCIPLE_ICONS.length]} weight="medium" className="principle-icon" />
          <h3 className="principle-title">{principle.title}</h3>
          <p className="principle-body">{principle.body}</p>
        </li>
      ))}
    </ol>
  );
}

function About() {
  return (
    <section id="about" className="section home-about" data-nav-section="about">
      <div className="shell">
        <header className="section-head" data-reveal>
          <Statement size="l" lead="About me." text={ABOUT.statement} />
        </header>

        <div className="about-intro">
          <Story />
          <Specs />
        </div>

        <Principles />
      </div>
    </section>
  );
}

export default About;
