import { useEffect } from "react";

const byDocumentOrder = (a, b) =>
  a.target.compareDocumentPosition(b.target) & Node.DOCUMENT_POSITION_FOLLOWING ? -1 : 1;

// Elements that enter the viewport together reveal as one staggered group:
// each gets --i (its place in the batch) unless it already sets its own.
export default function useReveal(rootRef, key) {
  useEffect(() => {
    const root = rootRef?.current;
    if (!root) return undefined;

    const items = Array.from(root.querySelectorAll("[data-reveal]:not([data-revealed])"));
    if (!items.length) return undefined;

    if (typeof IntersectionObserver === "undefined") {
      items.forEach((el) => el.setAttribute("data-revealed", ""));
      return undefined;
    }

    const timers = [];
    const observer = new IntersectionObserver(
      (entries) => {
        entries
          .filter((entry) => entry.isIntersecting)
          .sort(byDocumentOrder)
          .forEach((entry, i) => {
            const el = entry.target;
            if (!el.style.getPropertyValue("--i")) el.style.setProperty("--i", Math.min(i, 6));
            el.setAttribute("data-revealed", "");
            observer.unobserve(el);
            // Hand the element back to its own transitions once the entrance is over.
            timers.push(setTimeout(() => el.setAttribute("data-settled", ""), 1500 + i * 70));
          });
      },
      { rootMargin: "0px 0px -8% 0px" }
    );

    items.forEach((el) => observer.observe(el));
    return () => {
      observer.disconnect();
      timers.forEach(clearTimeout);
    };
  }, [rootRef, key]);
}
