import { forwardRef } from "react";
import { flushSync } from "react-dom";
import { Link, useLocation, useNavigate } from "react-router-dom";
import { prefersReducedMotion } from "../routes";

// Resolves once `ready()` is true (checked every ~16ms), or after `limit` ms regardless.
const waitFor = (ready, limit = 1500) =>
  new Promise((resolve) => {
    const start = Date.now();
    const check = () => (ready() || Date.now() - start > limit ? resolve() : setTimeout(check, 16));
    check();
  });

// React Router renders route changes as React transitions, so right after navigate() the old
// page can still be on screen (and a lazy page's first visit may show the Suspense fallback).
// The shell writes the committed pathname to <html data-route>; wait for it to match.
const pathOf = (to) => (String(to).split(/[?#]/)[0] || "/").replace(/(.)\/+$/, "$1");
const pageRendered = (to) =>
  document.documentElement.dataset.route === pathOf(to) && !document.querySelector(".route-fallback");

const plainClick = (e) =>
  !e.defaultPrevented && e.button === 0 && !e.metaKey && !e.ctrlKey && !e.shiftKey && !e.altKey;

// Runs a route change inside a View Transition. `prepare` loads the next page's code first.
//  - morphEl: an element on this page that grows into the next page's project media
//  - shellEl: a card on this page that expands into the next page's side panel (pv-info)
//  - pairs: extra [element, name] shared elements, e.g. the home folder → the Work header icon
//  - morphTo: a project id; on the next page, its [data-morph-id] element (and its card)
//    become the targets the current project shrinks back into (scrolled into view first)
//  - dir ("next" | "prev"): a move between projects; replace swaps the history entry
export function startPageTransition(
  navigate,
  to,
  { prepare, morphEl, shellEl, pairs = [], morphTo, dir, replace = false } = {}
) {
  const root = document.documentElement;
  const go = () => navigate(to, { replace });

  if (!document.startViewTransition || prefersReducedMotion()) {
    return Promise.resolve(prepare?.()).catch(() => {}).then(go);
  }

  return Promise.resolve(prepare?.())
    .catch(() => {})
    .then(() => {
      const named = [];
      const name = (el, n) => {
        if (!el) return;
        el.style.viewTransitionName = n;
        named.push(el);
      };
      name(morphEl, "project-media");
      name(shellEl, "pv-info");
      pairs.forEach(([el, n]) => name(el, n));
      root.dataset.vt = morphEl || morphTo || pairs.length ? "morph" : "page";
      if (shellEl || morphTo) root.dataset.shell = "";
      if (dir) root.dataset.dir = dir;
      const transition = document.startViewTransition(async () => {
        root.dataset.keepScroll = "";
        flushSync(go);
        await waitFor(
          () => pageRendered(to) && (!morphTo || document.querySelector(`[data-morph-id="${morphTo}"]`))
        );
        if (!dir && !String(to).includes("#")) window.scrollTo(0, 0);
        if (morphTo) {
          const target = document.querySelector(`[data-morph-id="${morphTo}"]`);
          if (target) {
            target.scrollIntoView({ block: "center" });
            name(target, "project-media");
            name(target.closest("[data-morph-shell]"), "pv-info");
          }
        }
      });
      // A transition is skipped (and `ready` rejects) if the tab is hidden; that's fine.
      transition.ready.catch(() => {});
      transition.finished.finally(() => {
        delete root.dataset.vt;
        delete root.dataset.dir;
        delete root.dataset.shell;
        named.forEach((el) => (el.style.viewTransitionName = ""));
      });
    });
}

const TransitionLink = forwardRef(function TransitionLink(
  { to, prepare, morph = false, shell = false, morphTo, pairs, onClick, target, ...rest },
  ref
) {
  const navigate = useNavigate();
  const { pathname } = useLocation();

  const handleClick = (e) => {
    onClick?.(e);
    if (!plainClick(e) || target === "_blank") return;
    const nextPath = String(to).split("#")[0] || "/";
    if (nextPath === pathname) {
      // Same page: no transition, just move to the section (or the top).
      if (!String(to).includes("#")) {
        e.preventDefault();
        window.scrollTo({ top: 0, behavior: prefersReducedMotion() ? "auto" : "smooth" });
      }
      return;
    }
    if (!document.startViewTransition || prefersReducedMotion()) return;
    e.preventDefault();
    const morphEl = morph ? e.currentTarget.querySelector("[data-morph]") : null;
    const shellEl = shell ? e.currentTarget : null;
    startPageTransition(navigate, to, { prepare, morphEl, shellEl, morphTo, pairs: pairs?.() || [] });
  };

  return <Link ref={ref} to={to} target={target} onClick={handleClick} {...rest} />;
});

export default TransitionLink;
