import { useEffect } from "react";

const LIT = ".card, .project-card, .hero-status";

// Cards track the cursor in --px/--py for their spotlight. Nothing is moved here:
// hovered elements stay put so they never slide out from under the pointer.
export default function usePointerFX() {
  useEffect(() => {
    const fine = window.matchMedia?.("(hover: hover) and (pointer: fine)").matches;
    if (!fine) return undefined;

    let frame = 0;
    let last = null;

    const paint = () => {
      frame = 0;
      const e = last;
      const card = e?.target instanceof Element ? e.target.closest(LIT) : null;
      if (!card) return;
      const box = card.getBoundingClientRect();
      card.style.setProperty("--px", `${e.clientX - box.left}px`);
      card.style.setProperty("--py", `${e.clientY - box.top}px`);
    };

    const move = (e) => {
      last = e;
      if (!frame) frame = requestAnimationFrame(paint);
    };

    document.addEventListener("pointermove", move, { passive: true });
    return () => {
      cancelAnimationFrame(frame);
      document.removeEventListener("pointermove", move);
    };
  }, []);
}
