import { useCallback, useEffect, useState } from "react";

const KEY = "theme";
const COLORS = { light: "#f5f5f7", dark: "#000000" };

const darkQuery = () =>
  typeof window !== "undefined" && window.matchMedia
    ? window.matchMedia("(prefers-color-scheme: dark)")
    : null;

function stored() {
  try {
    const value = localStorage.getItem(KEY);
    return value === "light" || value === "dark" ? value : null;
  } catch {
    return null;
  }
}

function apply(theme) {
  document.documentElement.dataset.theme = theme;
  document
    .querySelectorAll('meta[name="theme-color"]')
    .forEach((meta) => meta.setAttribute("content", COLORS[theme]));
  try {
    localStorage.setItem(KEY, theme);
  } catch {
  }
}

export default function useTheme() {
  const [theme, setTheme] = useState(
    () => stored() || (darkQuery()?.matches ? "dark" : "light")
  );

  useEffect(() => {
    const query = darkQuery();
    if (!query || stored()) return undefined;
    const onChange = (e) => {
      if (!stored()) setTheme(e.matches ? "dark" : "light");
    };
    query.addEventListener?.("change", onChange);
    return () => query.removeEventListener?.("change", onChange);
  }, []);

  const toggle = useCallback((event) => {
    const next = theme === "dark" ? "light" : "dark";
    const calm = window.matchMedia?.("(prefers-reduced-motion: reduce)").matches;

    if (document.startViewTransition && !calm) {
      // The new appearance spreads out of the button as a circle.
      const root = document.documentElement;
      const box = event?.currentTarget?.getBoundingClientRect?.();
      const x = box ? box.left + box.width / 2 : window.innerWidth / 2;
      const y = box ? box.top + box.height / 2 : 0;
      const r = Math.hypot(Math.max(x, window.innerWidth - x), Math.max(y, window.innerHeight - y));
      root.style.setProperty("--vt-x", `${x}px`);
      root.style.setProperty("--vt-y", `${y}px`);
      root.style.setProperty("--vt-r", `${r}px`);
      root.dataset.vt = "theme";
      const transition = document.startViewTransition(() => apply(next));
      transition.ready.catch(() => {});
      transition.finished.finally(() => delete root.dataset.vt);
    } else {
      apply(next);
    }
    setTheme(next);
  }, [theme]);

  return [theme, toggle];
}
